// ─── Build Anthropic API request body ────────────────────────────────────────
// Incoming payload from maxentertain.com chat widget:
//   message    – current user message (string)
//   history    – previous messages [{ role, content }]
//   context    – compact property info text (injected by the Next.js API route)
//   sessionId  – client IP used for session tracking

const data = $input.first().json;
const message   = String(data.message   || '').slice(0, 2000);
const history   = Array.isArray(data.history) ? data.history : [];
const context   = String(data.context   || '');
const sessionId = String(data.sessionId || 'unknown');

if (!message) {
  throw new Error('Empty message received');
}

const systemPrompt = [
  'You are MAX, the virtual concierge for MAX Entertain Beachside Retreat — a luxury vacation rental in Tootgarook, Victoria, Australia.',
  'Answer questions ONLY using the property information in the CONTEXT section below.',
  'If information is not covered by the context, say so politely and suggest the guest contacts the host via the enquiry form at /inquiry.',
  'NEVER invent prices, availability, contact numbers, or policies not in the context.',
  'Keep responses concise, warm, and helpful. Use bullet points where appropriate.',
  'If asked about topics unrelated to the property, politely redirect to property questions.',
  '',
  'CONTEXT:',
  context
].join('\n');

// Build messages array — no system role in Anthropic format (system is separate)
const messages = [
  ...history
    .filter(m => m.role === 'user' || m.role === 'assistant')
    .slice(-18)  // keep last 18 turns for context window safety
    .map(m => ({ role: m.role, content: String(m.content).slice(0, 2000) })),
  { role: 'user', content: message }
];

const requestBody = JSON.stringify({
  model: 'claude-haiku-4-5',
  system: systemPrompt,
  messages,
  max_tokens: 700,
  temperature: 0.2
});

return [{ json: { requestBody, sessionId } }];

// Extract the assistant reply from the Anthropic response
const data = $input.first().json;

// Handle API-level errors returned in the response body
if (data.type === 'error' || data.error) {
  const errMsg = data.error?.message || 'API error';
  console.error('Anthropic error:', errMsg);
  return [{ json: { reply: "I'm experiencing a technical issue right now. Please try again or contact us via the enquiry form at /inquiry." } }];
}

const reply =
  data?.content?.[0]?.text?.trim() ||
  "I'm sorry, I couldn't generate a response. Please contact the host via the enquiry form at /inquiry.";

return [{ json: { reply } }];

// ─── OpenAI alternative ──────────────────────────────────────────────────────
// Swap this node for 'Build Prompt' if you prefer GPT over Claude.
// 1. Point Call AI node URL to: https://api.openai.com/v1/chat/completions
// 2. Set credential header name to 'Authorization' and value to 'Bearer YOUR_KEY'
// 3. Change Extract Reply to use: data?.choices?.[0]?.message?.content

const data = $input.first().json;
const message   = String(data.message   || '').slice(0, 2000);
const history   = Array.isArray(data.history) ? data.history : [];
const context   = String(data.context   || '');
const sessionId = String(data.sessionId || 'unknown');

if (!message) throw new Error('Empty message');

const systemPrompt = [
  'You are MAX, the virtual concierge for MAX Entertain Beachside Retreat — a luxury vacation rental in Tootgarook, Victoria, Australia.',
  'Answer questions ONLY using the property information in the CONTEXT section below.',
  'If information is not covered by the context, say so politely and suggest the guest contacts the host via the enquiry form at /inquiry.',
  'NEVER invent prices, availability, contact numbers, or policies not in the context.',
  'Keep responses concise, warm, and helpful. Use bullet points where appropriate.',
  '',
  'CONTEXT:',
  context
].join('\n');

// OpenAI: system message goes inside the messages array
const messages = [
  { role: 'system', content: systemPrompt },
  ...history
    .filter(m => m.role === 'user' || m.role === 'assistant')
    .slice(-18)
    .map(m => ({ role: m.role, content: String(m.content).slice(0, 2000) })),
  { role: 'user', content: message }
];

const requestBody = JSON.stringify({
  model: 'gpt-4o-mini',
  messages,
  max_tokens: 700,
  temperature: 0.2
});

return [{ json: { requestBody, sessionId } }];
